Run it:
```js
import assert from "node:assert/strict";
function describeTrip({ traveler: { name = "Guest" } = {}, to = "Unknown", bags = 0 } = {}) {
  return `${name} → ${to} (${bags} bags)`;
}
const trip = { traveler: { name: "Ana" }, to: "Quito", bags: 2 };
assert.equal(describeTrip(trip), "Ana → Quito (2 bags)");
assert.equal(describeTrip(), "Guest → Unknown (0 bags)");
const moved = { ...trip, to: "Cusco" };
assert.equal(moved.to, "Cusco");
assert.equal(trip.to, "Quito");               // original untouched
assert.equal(moved.traveler, trip.traveler);  // shallow: nested object is shared
console.log(describeTrip(moved));
```
